// Morgen-Briefing und System-Mails (ALLY 33, BA5, Stefan 20.10.2026): zwei Seiten aus dem Register (morgen-briefing, system-mails).
// Migration 208 (eine Funktion „Briefing“, Stefan 06.11.2026): die Seite morgen-briefing ist die Seite „Briefing“ (briefing_web, Daten br); der alte Aufruf briefings (KI-Analysen) zeigt sie ebenfalls.
// Daten wie ALLY 8: ally_web_arbeit (Briefing), arbeit_web_seite 'systemmails'. Aktionen mit den Namen und Feldern von ALLY 8:
// start (was=briefing, "Jetzt schicken"), systemmails (tage, Zusammenfassung). Liefert nur die Seitenbeschreibung (JSON).
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
// BA10 (Migration 69): Morgen-Briefing – Abschnitt „Letzte Briefings“ (ally_ergebnisse_ui, nur eigene), Lesen im Seitenfenster (er=<id>).
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const seite = String(E.seite || '') === 'system-mails' ? 'system-mails' : 'morgen-briefing';   // Migration 208 (eine Funktion „Briefing“, Stefan 06.11.2026): briefings = Briefing
const titel = String(F.name || (seite === 'system-mails' ? 'System-Mails' : 'Briefing'));
const kopf = { schluessel: seite, art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
const zahnrad = /^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || '')) ? { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } : null;
if (zahnrad) kopf.zahnrad = { ziel: zahnrad };
const fehler = t => [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: t }] } } }];
if (D.ok !== true) return fehler('Die Seite konnte nicht geladen werden. Bitte neu laden.');
const ZU = D.zustand || {};
const zahl = n => Number(n || 0).toLocaleString('de-DE');

// ---------- Briefing (Migration 208, Stefan 06.11.2026: Morgen-Briefing und KI-Analysen sind eine Funktion „Briefing“) ----------
// Daten und Rechte aus briefing_web. Ansichten: Liste „Meine Briefings“ und darunter die Briefings, die andere an mich zustellen oder mit mir teilen (Kopfknopf
// „Neues Briefing“, Papierkorb als Symbol); Seite eines Briefings (briefing=<Nummer>): Ergebnis mit Kopf und vollem Text, Kacheln Zeitplan, Inhalte, Empfänger
// (nur mit dem Recht „Briefings für andere“), Zustellung, Teilen; Verlauf (ergebnis=<Nummer> zeigt ein älteres); Papierkorb (papierkorb=1).
// Je Kachel genau ein Formular mit einem Knopf „Speichern“; Auswahl immer als Dropdown. Der alte Aufruf der Seite KI-Analysen (Seite briefings) zeigt dieselbe Seite.
if (seite === 'morgen-briefing') {
  const R = D.br;
  const s = v => String(v ?? '');
  const L = x => Array.isArray(x) ? x : [];
  const id9 = v => /^[0-9]{1,9}$/.test(s(v)) ? s(v) : '';
  const id12 = v => /^[0-9]{1,12}$/.test(s(v)) ? s(v) : '';
  const SEITE = 'morgen-briefing';
  const hier = p => ({ seite: SEITE, parameter: p || {} });
  kopf.schluessel = SEITE;
  kopf.krumen = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }];
  delete kopf.zahnrad;
  if (!R || typeof R !== 'object' || R.ok !== true) return fehler(s((R && R.fehler) || 'Die Briefings konnten nicht geladen werden. Bitte neu laden.'));
  const zusammen = (...t) => t.filter(Boolean).join(' · ');
  const TAGE = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
  const RH = [{ wert: 'tag', text: 'Täglich' }, { wert: 'woche', text: 'Wöchentlich' }, { wert: 'monat', text: 'Monatlich' }, { wert: 'hand', text: 'Nur von Hand' }];
  const ZR = L(R.zeitraeume).length ? L(R.zeitraeume) : [{ wert: 'letzte_7_tage', text: 'Letzte 7 Tage' }, { wert: 'letzte_30_tage', text: 'Letzte 30 Tage' }, { wert: 'vormonat', text: 'Vormonat' }];
  const PLAN_INFO = 'Wann Ally das Briefing von selbst erstellt, zum Beispiel täglich um 05:00. „Nur von Hand“ oder aus: Es entsteht nur mit „Jetzt erstellen“.';
  // Zeitplan-Felder (Neues Briefing und Kachel): Rhythmus, Wochentag bzw. Tag im Monat, Uhrzeit im 15-Minuten-Raster; nur sichtbar, wenn sie gelten
  const planFelder = (w0, mitAn) => {
    const an = mitAn ? { zeigen_wenn: { feld: 'an', werte: ['1'] } } : {};
    const und = werte => mitAn ? { zeigen_wenn: [{ feld: 'an', werte: ['1'] }, { feld: 'rhythmus', werte: werte }] } : { zeigen_wenn: { feld: 'rhythmus', werte: werte } };
    return (mitAn ? [{ typ: 'haken', name: 'an', label: 'Eingeschaltet', an: w0.an !== false, breite: 'voll', info: 'Aus: Ally erstellt das Briefing nicht nach Zeitplan. „Jetzt erstellen“ geht weiter.' }] : []).concat([
      Object.assign({ typ: 'auswahl', name: 'rhythmus', label: 'Rhythmus', ausklappliste: true, wert: s(w0.rhythmus || 'tag'), optionen: RH, info: PLAN_INFO }, an),
      Object.assign({ typ: 'auswahl', name: 'tag', label: 'Wochentag', ausklappliste: true, wert: s(Number(w0.tag) <= 7 ? w0.tag : '1'), optionen: TAGE.map((t, i) => ({ wert: String(i + 1), text: t })) }, und(['woche'])),
      Object.assign({ typ: 'auswahl', name: 'monatstag', label: 'Tag im Monat', ausklappliste: true, wert: s(w0.rhythmus === 'monat' ? w0.tag : '1'),
        optionen: Array.from({ length: 28 }, (_, i) => ({ wert: String(i + 1), text: (i + 1) + '.' })) }, und(['monat'])),
      Object.assign({ typ: 'zeit', name: 'uhrzeit', label: 'Uhrzeit', wert: s(w0.uhrzeit || '05:00'), schritt: 900, info: 'Im 15-Minuten-Takt, deutsche Zeit.' }, und(['tag', 'woche', 'monat']))]);
  };
  // Text eines Ergebnisses in Bausteine (Absätze; mehrzeilige Absätze mit kurzer erster Zeile = Überschrift und Liste), wie bisher
  const textBloecke = t => {
    const aus = [];
    for (const abs of String(t || '').split(/\n{2,}/)) {
      const z = abs.split('\n').map(x => x.trim()).filter(Boolean);
      if (!z.length) continue;
      if (z.length === 1) { aus.push({ typ: 'text', text: z[0] }); continue; }
      let st = 0;
      if (/:$/.test(z[0]) || (z[0].length <= 60 && !/^[-•]/.test(z[0]))) { aus.push({ typ: 'unterueberschrift', text: z[0].replace(/:$/, '') }); st = 1; }
      aus.push({ typ: 'liste', eintraege: z.slice(st).map(x => ({ text: x.replace(/^[-•]\s*/, '') })) });
    }
    return aus.length ? aus : [{ typ: 'text', ton: 'grau', text: 'Kein Text gespeichert.' }];
  };
  let abschnitte = [], bloecke = null;
  const fenster = [];
  const B = R.briefing && typeof R.briefing === 'object' && id9(R.briefing.id) ? R.briefing : null;
  const P0 = ($('Parameter').first().json || {}).p || {};

  if ((id9(P0.briefing) || R.briefing_fehlt === true) && !B) {
    kopf.krumen = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel, ziel: hier() }, { text: 'Briefing' }];
    bloecke = [{ typ: 'hinweis', ton: 'warn', text: 'Dieses Briefing gibt es nicht oder es ist nicht mit dir geteilt.' }, { typ: 'aktion', text: 'Zu den Briefings', ziel: hier() }];
  } else if (B) {
    // ---------- Seite eines Briefings ----------
    const bid = id9(B.id), w = { briefing_id: bid }, darf = B.darf_aendern === true && B.geloescht !== true;
    const ER = L(B.ergebnisse), EL = L(B.empfaenger_liste);
    kopf.titel = s(B.name);
    kopf.beschreibung = zusammen(B.eigen ? '' : (B.von ? 'von ' + s(B.von) : ''), s(B.zeitplan), L(B.inhalte_namen).length ? L(B.inhalte_namen).length + ' Inhalte' : 'keine Inhalte', B.geloescht ? 'im Papierkorb' : '');
    kopf.krumen = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel, ziel: hier() }].concat(B.geloescht ? [{ text: 'Papierkorb', ziel: hier({ papierkorb: '1' }) }] : []).concat([{ text: s(B.name) }]);
    if (B.geloescht) {
      if (B.darf_aendern) kopf.hauptaktion = { text: 'Wiederherstellen', aktion: 'br_wiederherstellen', werte: w, frage: 'Briefing „' + s(B.name) + '“ wiederherstellen? Danach erstellt Ally es wieder nach seinem Zeitplan.' };
    } else {
      // „Jetzt erstellen“: Ergebnis für mich, auf dieser Seite; Chat, Glocke und Mail nur, wenn so eingestellt und ich es bekomme (keine Chatnachricht ohne Häkchen Chat)
      const wege = B.ich_empfaenger ? [B.chat ? 'im Chat' : '', B.glocke ? 'in der Glocke' : '', B.mail ? 'per Mail' : ''].filter(Boolean) : [];
      if (B.darf_erstellen === true) kopf.hauptaktion = { text: 'Jetzt erstellen', aktion: 'br_jetzt', werte: w,
        frage: 'Briefing „' + s(B.name) + '“ jetzt für dich erstellen? Es steht danach auf dieser Seite' + (wege.length ? ', außerdem ' + wege.join(', ') : '') + '. Der Zeitplan bleibt, wie er ist.' };
      if (darf) {
        kopf.aktionen = [{ text: 'Umbenennen', fenster: 'umbenennen' }, { text: 'In den Papierkorb', aktion: 'br_papierkorb', werte: w,
          frage: 'Briefing „' + s(B.name) + '“ in den Papierkorb legen? Ally erstellt es dann nicht mehr. Im Papierkorb kannst du es wiederherstellen oder endgültig löschen.' }];
        fenster.push({ id: 'umbenennen', art: 'dialog', titel: 'Umbenennen', inhalt: [{ typ: 'formular', id: 'umbenennen', aktion: 'br_umbenennen', werte: w, spalten: 1,
          felder: [{ typ: 'text', name: 'name', label: 'Name', wert: s(B.name), pflicht: true, max: '80', breite: 'voll' }],
          knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Speichern' }] }] });
      }
    }
    // Kennzahlen: nächstes nach Zeitplan, Empfänger, letztes Ergebnis (Stefans Beobachtung: nie „aus“ und „geschickt“ zugleich – aus zeigt kein „Heute“)
    bloecke = [{ typ: 'kennzahlen', eintraege: [
      { label: 'Nächstes', wert: B.naechster ? s(B.naechster).split(', ').slice(0, 2).join(', ') : (B.an === false ? 'aus' : 'nur von Hand'),
        neben: B.naechster ? s(B.naechster).split(', ')[2] || '' : 'mit „Jetzt erstellen“' },
      { label: 'Empfänger', wert: String(EL.filter(e => !e.abbestellt).length), neben: EL.filter(e => !e.abbestellt).length ? EL.filter(e => !e.abbestellt).map(e => e.eigen && B.eigen ? 'du' : s(e.name)).slice(0, 3).join(', ') + (EL.length > 3 ? ' …' : '') : 'niemand' },
      { label: 'Letztes Ergebnis', wert: ER.length ? s(ER[0].erstellt_am).split(' ')[0] : '–', neben: ER.length ? s(ER[0].erstellt_am).split(' ')[1] || '' : 'noch keins' }] }];
    // Ergebnis mit Kopf (wie Migration 180): Erstellt am, Erstellt von, Für, Zeitraum, Talents, Stand der Zahlen, Zugestellt, KI; darunter der volle Text
    const EG = B.ergebnis && typeof B.ergebnis === 'object' && id12(B.ergebnis.id) ? B.ergebnis : null;
    abschnitte.push({ id: 'ergebnis', titel: EG && ER.length && s(ER[0].id) !== s(EG.id) ? 'Ergebnis vom ' + s(EG.erstellt_am) : 'Ergebnis', offen_standard: true,
      info: ['Das neueste Ergebnis, das du lesen darfst; ältere stehen im Verlauf.'],
      inhalt: EG ? [{ typ: 'paare', eintraege: [{ label: 'Erstellt am', wert: s(EG.erstellt_am) }, { label: 'Erstellt von', wert: s(EG.erstellt_von) }]
          .concat(s(EG.person) !== s(R.ich) ? [{ label: 'Für', wert: s(EG.fuer) }] : [])
          .concat(EG.zeitraum ? [{ label: 'Zeitraum der Daten', wert: s(EG.zeitraum) }] : [])
          .concat(EG.talents ? [{ label: 'Talents', wert: s(EG.talents) }, { label: 'Stand der Zahlen', wert: s(EG.stand_zahlen) }] : [])
          .concat([{ label: 'Zugestellt', wert: s(EG.zugestellt), ton: EG.zustell_warn === true ? 'warn' : '' }])
          .concat(EG.ki ? [{ label: 'KI', wert: s(EG.ki), ton: EG.ki_ok === false ? 'warn' : '' }] : []) }].concat(textBloecke(EG.text))
        : [{ typ: 'text', ton: 'grau', text: B.darf_erstellen === true ? 'Noch kein Ergebnis. „Jetzt erstellen“ erstellt es sofort.' : 'Noch kein Ergebnis für dich.' }] });
    // Kacheln: je Kachel ein Formular mit Aktion br_speichern und teil; ohne Ändern-Recht gesperrt mit „Anzeigen“
    const kachel = (id, felder, extra) => Object.assign({ typ: 'formular', id: 'br-' + id, aktion: 'br_speichern', werte: Object.assign({ teil: id }, w), spalten: 2, felder },
      darf ? {} : { gesperrt: true }, extra || {});
    const sperren = f => darf ? f : f.typ === 'mehrfach' ? Object.assign({}, f, { optionen: L(f.optionen).map(o => Object.assign({}, o, { gesperrt: true })) }) : Object.assign({}, f, { gesperrt: true });
    const anzeigen = darf ? {} : { kachel_aktion: 'Anzeigen' };
    // 1. Zeitplan
    abschnitte.push(Object.assign({ id: 'zeitplan', titel: 'Zeitplan', offen_standard: false, info: [PLAN_INFO],
      inhalt: [{ typ: 'paare', eintraege: [{ label: 'Zeitplan', wert: s(B.zeitplan) }].concat(B.naechster ? [{ label: 'Nächstes', wert: s(B.naechster) }] : []) },
        kachel('zeitplan', planFelder(B, true).map(sperren))] }, anzeigen));
    // 2. Inhalte: Bausteine nach Bereich gruppiert, ankreuzen und Optionen (Optionen erst, wenn der Baustein gewählt ist)
    const BS = L(B.bausteine), TO = L(R.auswahl_talents);
    const fInhalte = [{ typ: 'versteckt', name: 'bausteine_sichtbar', wert: '1' }];
    let gr = '';
    for (const x of BS) {
      if (s(x.gruppe) !== gr) { gr = s(x.gruppe); fInhalte.push({ typ: 'unterueberschrift', text: gr }); }
      const k = s(x.schluessel), wv = x.werte && typeof x.werte === 'object' ? x.werte : {};
      fInhalte.push(sperren({ typ: 'haken', name: 'bs__' + k, label: s(x.name) + (x.ki ? ' (KI-Kosten)' : ''), an: x.gewaehlt === true, breite: 'voll', info: s(x.beschreibung) }));
      for (const o of L(x.optionen)) {
        const zw = { zeigen_wenn: { feld: 'bs__' + k, werte: ['1'] } };
        if (o.art === 'talents') fInhalte.push(darf ? Object.assign({ typ: 'mehrfach', auswahlliste: true, name: 'bo__' + k + '__' + s(o.name), label: s(o.label || 'Weitere Talents'), breite: 'voll',
            wert: L(wv[o.name]).map(s), optionen: TO.map(t => ({ wert: s(t.wert), text: s(t.text) })),
            info: 'Deine eigenen Talents sind immer dabei' + (L(R.eigene_talents).length ? ' (' + L(R.eigene_talents).map(s).join(', ') + ')' : '') + '. Hier wählst du weitere.' }, zw)
          : Object.assign({ typ: 'text', name: 'bo_anzeige_' + k, label: s(o.label || 'Weitere Talents'), wert: L(wv[o.name]).length ? L(wv[o.name]).length + ' weitere' : 'keine weiteren', gesperrt: true, breite: 'voll' }, zw));
        else if (o.art === 'zeitraum') fInhalte.push(sperren(Object.assign({ typ: 'auswahl', name: 'bo__' + k + '__' + s(o.name), label: s(o.label || 'Zeitraum'), ausklappliste: true,
          wert: s(wv[o.name] || 'letzte_7_tage'), optionen: ZR.map(z => ({ wert: s(z.wert), text: s(z.text) })), info: 'Verglichen wird mit dem gleich langen Zeitraum davor (Vormonat: mit dem Monat davor).' }, zw)));
      }
    }
    abschnitte.push(Object.assign({ id: 'inhalte', titel: 'Inhalte', offen_standard: false,
      info: ['Was im Briefing steht. Zur Auswahl stehen die Inhalte der Bereiche, die eure Organisation nutzt und für die du das Recht hast. Leere Inhalte stehen kurz unter „Sonst nichts offen“.'],
      inhalt: [{ typ: 'paare', eintraege: [{ label: 'Inhalte', wert: L(B.inhalte_namen).length ? L(B.inhalte_namen).map(s).join(', ') : 'keine' }] },
        kachel('inhalte', BS.length ? fInhalte : [{ typ: 'text', name: 'keine', label: 'Inhalte', wert: 'Für dich stehen keine Inhalte zur Wahl.', gesperrt: true, breite: 'voll' }])] }, anzeigen));
    // 3. Empfänger. Stefan 06.11.2026: „wer das Briefing bekommt, entscheidet, wer es anlegt“ – Häkchen „An mich“ (jede Besitzerin); weitere Empfänger und
    // „Alle Manager/innen der Talents“ (Kreis: Talents dieses Briefings oder alle aktiven) nur mit dem Recht „Briefings für andere“. Wer abbestellt hat, steht mit
    // „(abbestellt)“ dabei (nur bei der Besitzerin, Prüfung N-a).
    const empfText = EL.map(e => s(e.name) + (e.eigen ? '' : e.abbestellt ? ' (abbestellt)' : e.talent ? ' (Talent)' : e.manager ? ' (Manager/in)' : '')).join(', ');
    const darfE = darf && R.darf_andere === true;
    const andereText = EL.filter(e => !e.eigen).map(e => s(e.name) + (e.abbestellt ? ' (abbestellt)' : e.talent ? ' (Talent)' : e.manager ? ' (Manager/in)' : '')).join(', ');
    const fEmpf = [{ typ: 'versteckt', name: 'an_mich_sichtbar', wert: '1' },
      { typ: 'haken', name: 'an_mich', label: 'An mich', an: B.an_mich !== false, breite: 'voll', info: 'Aus: Du bekommst das Briefing nicht (es geht nur an die Empfänger unten); „Jetzt erstellen“ geht weiter.' }]
      .concat(darfE ? [{ typ: 'versteckt', name: 'empfaenger_sichtbar', wert: '1' }] : [])
      .concat(darfE && (B.manager_moeglich === true || B.manager === true) ? [{ typ: 'versteckt', name: 'manager_sichtbar', wert: '1' },
        { typ: 'haken', name: 'manager', label: 'Alle Manager/innen der Talents', an: B.manager === true, breite: 'voll',
          info: 'Bei jedem Lauf alle Personen, die für die Talents zuständig sind; jede bekommt ihre eigenen Talents. Neue kommen automatisch dazu.' },
        { typ: 'auswahl', name: 'manager_kreis', label: 'Welche Talents', ausklappliste: true, wert: B.manager_kreis === 'alle' ? 'alle' : 'briefing', zeigen_wenn: { feld: 'manager', werte: ['1'] },
          optionen: [{ wert: 'briefing', text: 'Talents dieses Briefings' }, { wert: 'alle', text: 'Alle aktiven Talents' }] }]
        : !darfE && B.manager === true ? [{ typ: 'text', name: 'manager_anzeige', label: 'Alle Manager/innen der Talents', wert: B.manager_kreis === 'alle' ? 'ja, alle aktiven Talents' : 'ja', gesperrt: true, breite: 'voll' }] : [])
      .concat([darfE ? { typ: 'mehrfach', auswahlliste: true, name: 'empfaenger', label: 'Weitere Empfänger', breite: 'voll', wert: L(B.empfaenger).map(s),
          optionen: L(R.auswahl_empfaenger).map(p => ({ wert: s(p.wert), text: s(p.text) })), info: 'Höchstens 50. Wer es abbestellt, bekommt es nicht mehr.' }
        : { typ: 'text', name: 'empfaenger_anzeige', label: 'Weitere Empfänger', wert: andereText || 'keine', gesperrt: true, breite: 'voll' }]);
    abschnitte.push(Object.assign({ id: 'empfaenger', titel: 'Empfänger', offen_standard: false,
      info: ['Für jede Person entsteht ein eigenes Ergebnis mit ihren Daten, zum Beispiel ihren Terminen und Mails. Talents lesen es in ihrem Bereich unter „Dein Briefing“.'],
      inhalt: [{ typ: 'paare', eintraege: [{ label: 'Bekommen es', wert: empfText || 'niemand (nur „Jetzt erstellen“)' }]
          .concat(darf && EL.some(e => e.abbestellt) ? [{ label: 'Abbestellt', wert: EL.filter(e => e.abbestellt).map(e => s(e.name)).join(', '), ton: 'warn' }] : []) },
        kachel('empfaenger', darf ? fEmpf : [{ typ: 'text', name: 'empfaenger_anzeige', label: 'Bekommen es', wert: empfText || 'niemand', gesperrt: true, breite: 'voll' }])] }, anzeigen));
    // 4. Zustellung: immer auf dieser Seite; dazu Chat, Glocke, Mail. Mail je Briefing (Stefan 06.11.2026, wie bisher bei den KI-Analysen): Absender-Postfach
    //    (Absender für Systemnachrichten oder ein Postfach mit erlaubtem Versand), Betreff, Text vor dem Briefing, Signatur, KI-Hinweis – erst sichtbar mit Häkchen Mail
    const zst = ['auf dieser Seite'].concat(B.chat ? ['im Chat'] : [], B.glocke ? ['in der Glocke'] : [], B.mail ? ['per Mail'] : []);
    const SYSA = R.system_absender && typeof R.system_absender === 'object' ? R.system_absender : null;
    const ABS = L(R.auswahl_absender).filter(x => x && s(x.adresse));
    const absName = a0 => { const p0 = ABS.find(x => s(x.adresse) === s(a0)); return p0 && s(p0.name) !== s(a0) ? s(p0.name) + ' (' + s(a0) + ')' : s(a0); };
    const AS = B.absender_stand && typeof B.absender_stand === 'object' ? B.absender_stand : {};
    const STD = B.mail_standard && typeof B.mail_standard === 'object' ? B.mail_standard : {};
    const sigArt = B.signatur_an === false ? 'keine' : s(B.signatur_html) ? 'eigen' : 'postfach';
    const anM = { feld: 'mail', werte: ['1'] };
    const EIN = { label: 'Platzhalter einfügen', optionen: L(B.platzhalter).filter(x => x && /^[A-Za-zÄÖÜäöüß]{1,30}$/.test(s(x.k))).map(x => ({ wert: '{' + s(x.k) + '}', text: s(x.k), info: s(x.info) })) };
    const mailFelder = darf ? [
      { typ: 'auswahl', name: 'absender', label: 'Absender-Postfach', breite: 'voll', ausklappliste: true, wert: s(B.absender || ''), zeigen_wenn: anM,
